                simpsonsRule += 1;
            } else if (i % 2 == 0) {
                simpsonsRule += 4*((Math.exp(e)-1)/Math.sin(e));
            } else if ((i % 2 != 0) && ( i > 1) && (i < valueN + 1)) {
                simpsonsRule += 2*((Math.exp(e)-1)/Math.sin(e));   
